                                                  const cRate = Number(expandedItemDetail.ratePerKg || 0);
                                                  const vRate = m?.revisedRatePerKg ?? 0;
                                                  const cPrice = cWeight * cRate;
                                                  const vPrice = vWeight * vRate;

                                                  const verifiedWeight = getVerifiedWeight('Casting Weight', vendor);

                                                  // Difference comparisons
                                                  const weightDiff = verifiedWeight !== null ? (verifiedWeight - cWeight) : (vWeight - cWeight);
                                                  const rateDiff = vRate - cRate;
                                                  const priceDiff = vPrice - cPrice;

